from test_bufftap import tests
from test_bufftap import test
from test_blessings import setup
scoped=setup+"IsInRaid=function() return true end; "

test('Group scope fixed choice differs from default class assignment',scoped+"BuffTap:SetGroupBlessingSettings('WARRIOR',0,'bow'); BuffTap:SetGroupBlessingSettings('WARRIOR',1,'bom'); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='bom'); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=2})=='bow')")
test('Groups one and three override all remaining groups',scoped+"BuffTap:SetGroupBlessingSettings('WARRIOR',0,'bow'); BuffTap:SetGroupBlessingSettings('WARRIOR',1,'bok'); BuffTap:SetGroupBlessingSettings('WARRIOR',3,'bok'); for i=1,8 do assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=i})==((i==1 or i==3) and 'bok' or 'bow')) end")
test('Group-specific priority list uses its own order',scoped+"BuffTap:SetGroupBlessingSettings('WARRIOR',1,nil,{'bow','bom'},true); BuffTap:SetGroupBlessingSettings('WARRIOR',1,'priority'); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='bow')")
test('Removing scope override restores all-groups choice',scoped+"BuffTap:SetGroupBlessingSettings('WARRIOR',1,'bow'); BuffTap:SetGroupBlessingSettings('WARRIOR',1,nil); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='bom')")
test('Player exception outranks scope and default',scoped+"BuffTap:SetGroupBlessingSettings('WARRIOR',1,'bok'); BuffTap:SetBlessingPlayer({unit='party1'},'bow'); assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='bow')")
test('Excluded group still outranks explicit scope choice',scoped+"BuffTap:SetGroupBlessingSettings('WARRIOR',1,'bok'); BuffTap.db.raidGroups[1]=false; assert(BuffTap:BlessingChoice({unit='party1',class='WARRIOR',group=1})=='skip')")
test('Moving player into another subgroup immediately changes effective assignment',scoped+"BuffTap:SetGroupBlessingSettings('WARRIOR',1,'bok'); local e={unit='party1',class='WARRIOR',group=1}; assert(BuffTap:BlessingChoice(e)=='bok'); e.group=2; assert(BuffTap:BlessingChoice(e)=='bom')")
raid=setup+"IsInRaid=function() return true end; GetNumGroupMembers=function() return 3 end; UnitExists=function(u) return true end; UnitGUID=function(u) return 'Player-'..(u=='raid1' and 'player' or u) end; UnitIsUnit=function(a,b) return a==b or a=='raid1' and b=='player' end; UnitClass=function(u) return 'Class',(u=='player' or u=='raid1') and 'PALADIN' or 'WARRIOR' end; GetRaidRosterInfo=function(i) return 'Name',0,i end; BuffTap:InvalidateRoster(); "
test('Conflicting same-class subgroup choices prevent Greater',raid+"BuffTap:SetGroupBlessingSettings('WARRIOR',2,'bok'); BuffTap:SetGroupBlessingSettings('WARRIOR',3,'bow'); refresh(); assert(not BuffTap.action.groupCast and BuffTap.action.key=='bok')")
test('Agreeing subgroup choices permit Greater across subgroups',raid+"BuffTap:SetGroupBlessingSettings('WARRIOR',2,'bok'); BuffTap:SetGroupBlessingSettings('WARRIOR',3,'bok'); refresh(); assert(BuffTap.action.id==25898 and BuffTap.action.groupCast)")
test('Scope change cancels prepared Greater at click',raid+"BuffTap:SetGroupBlessingSettings('WARRIOR',2,'bok'); BuffTap:SetGroupBlessingSettings('WARRIOR',3,'bok'); refresh(); assert(BuffTap.action.groupCast); BuffTap:SetGroupBlessingSettings('WARRIOR',3,'bow'); BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action)")
test('Scope config survives normalization and removes malformed keys',setup+"BuffTap.db.blessingGroupOverrides={[1]={classes={WARRIOR='bow'},priorities={WARRIOR={'bow','bom'}}},[9]={},bad=true}; BuffTap:InitDB(); assert(BuffTap.db.blessingGroupOverrides[1].classes.WARRIOR=='bow' and not BuffTap.db.blessingGroupOverrides[9] and not BuffTap.db.blessingGroupOverrides.bad)")
test('Combat cannot edit subgroup choices',setup+"combat=true; BuffTap:SetGroupBlessingSettings('WARRIOR',1,'bow'); assert(not BuffTap.db.blessingGroupOverrides[1])")
test('Scope editor saves only selected subgroup',setup+"BuffTap:Options(); local f=BuffTap.options; f.raidView.scripts.OnClick(); f.blessingScopeButtons[4].scripts.OnClick(); assert(f.blessingScope==3); f.blessingRows[1].pick.setChoice('bow'); assert(BuffTap.db.blessingGroupOverrides[3].classes.WARRIOR=='bow' and BuffTap.db.blessingClasses.WARRIOR=='bom')")
test('No-group scope setup is available before joining',setup+"GetNumSubgroupMembers=function() return 0 end; BuffTap:InvalidateRoster(); BuffTap:Options(); local f=BuffTap.options; f.raidView.scripts.OnClick(); f.blessingScopeButtons[4].scripts.OnClick(); f.blessingRows[1].pick.setChoice('bow'); assert(BuffTap.db.blessingGroupOverrides[3].classes.WARRIOR=='bow')")
print('ALL',len(tests),'SCENARIOS PASSED')
